import * as LAW from './dl-her-colours.mjs';
import * as WISH from './dl-her-wishes.mjs';
import * as REEL from './dl-her-reel.mjs';
import * as FRIEND from './dl-her-friends.mjs';
export * from './dl-her-colours.mjs';

export const SEEN_EVENT = 'dl-athena', SKIP_EVENT = 'dl-skip-to-mint';   // dl-athena.js's word (her 'landed') and dl-athena.mjs's (the film's skip to the mint)
